import{_ as o,o as i,c as t,ao as a}from"./chunks/framework.DlOpO9-F.js";const u=JSON.parse('{"title":"Right Now","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/right-now.md","filePath":"generated/grindr-api/right-now.md"}'),d={name:"grindr-api/right-now.md"};function n(s,e,l,r,c,h){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="right-now" tabindex="-1">Right Now <a class="header-anchor" href="#right-now" aria-label="Permalink to “Right Now”">​</a></h1><h2 id="get-own-right-now-post" tabindex="-1">Get own Right Now post <a class="header-anchor" href="#get-own-right-now-post" aria-label="Permalink to “Get own Right Now post”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Get the current Right Now post, including a hidden post before expiration. Returns {&quot;post&quot;:null} when there is no current post or it has expired.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v3/rightnow/active-post</span></span></code></pre></div><p>Response:</p><ul><li><code>post</code> — <a href="/grindr-api/right-now#rightnowpostdetails">RightNowPostDetails</a> or <code>null</code></li></ul><h2 id="get-right-now-post-by-profile" tabindex="-1">Get Right Now post by profile <a class="header-anchor" href="#get-right-now-post-by-profile" aria-label="Permalink to “Get Right Now post by profile”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Get a profile’s Right Now post. Uses activeText for live text and a flat media array rather than the feed’s type/data wrappers. Returns <code>{&quot;post&quot;:null}</code> when the profile has no post or its post is hidden, expired or discreet, including for a nonexistent profile ID. <code>locationRadius</code> is <code>null</code> for another profile&#39;s post.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v3/rightnow/profiles/{profileId}</span></span></code></pre></div><p>Response:</p><ul><li><code>post</code> — <a href="/grindr-api/right-now#rightnowpostdetails">RightNowPostDetails</a> or <code>null</code></li></ul><h2 id="update-right-now-post" tabindex="-1">Update Right Now post <a class="header-anchor" href="#update-right-now-post" aria-label="Permalink to “Update Right Now post”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Partially edit an existing Right Now post. Send only the fields being changed. Edits preserve the post identity and expiration. A new <code>locationRadius</code> also picks a new offset for the post&#39;s <code>lat</code> and <code>lon</code>. <code>text</code> accepts at least 500 characters. The v4 route ignores <code>isDiscreet</code> and <code>sharedFields</code> and turns a <code>NOT_SELECTED</code> <code>isDiscreet</code> into <code>FALSE</code>; v5 applies them. On v5, <code>isDiscreet: false</code> on a <code>TRUE</code> post is rejected.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATCH /{version}/rightnow/posts/{postId}</span></span></code></pre></div><p>Body:</p><ul><li><code>hosting</code> — boolean, optional</li><li><code>text</code> — string, submitted for moderation, so read <code>moderatedText</code> before assuming <code>activeText</code> has changed, optional</li><li><code>media</code> — array of objects that replaces the attached media, optional <ul><li><code>type</code> — string, <code>&quot;image_v1&quot;</code></li><li><code>data</code> — object <ul><li><code>id</code> — long integer, the <code>mediaId</code> returned by <a href="/grindr-api/right-now#upload-right-now-media">Upload Right Now media</a> or <a href="/grindr-api/right-now#upload-right-now-media-v2">Upload Right Now media (v2)</a>; one <code>mediaId</code> can be attached to more than one post</li></ul></li></ul></li><li><code>hidden</code> — boolean, whether the post is hidden, optional</li><li><code>shareLocation</code> — <a href="/grindr-api/right-now#rightnowsharelocation">RightNowShareLocation</a>, optional</li><li><code>locationRadius</code> — integer, location precision value. On this edit route, locationRadius = 100 − slider value. This is not a distance in meters, optional</li><li><code>isDiscreet</code> — boolean, applied on v5 only, optional</li><li><code>sharedFields</code> — array of strings, <code>&quot;AGE&quot;</code>, <code>&quot;HEIGHT&quot;</code>, <code>&quot;WEIGHT&quot;</code>, <code>&quot;POSITION&quot;</code>, applied on v5 only, optional</li></ul><p>Errors:</p><ul><li><code>400</code> — <code>urn:gr:err:resource_not_found</code> when no post has this ID. <code>urn:gr:err:internal_error</code> for a <code>hosting</code> that is not a boolean, such as <code>&quot;yes&quot;</code>, checked before the post ID. <code>urn:gr:err:client_action</code> on v5 for <code>isDiscreet: false</code> on a discreet post or for a <code>sharedFields</code> value outside the list.</li></ul><h2 id="create-right-now-post-v4" tabindex="-1">Create Right Now post (v4) <a class="header-anchor" href="#create-right-now-post-v4" aria-label="Permalink to “Create Right Now post (v4)”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Same as <a href="/grindr-api/right-now#create-right-now-post">Create Right Now post</a>, but the post starts <code>HIDDEN</code>; show it with <a href="/grindr-api/right-now#update-right-now-post-settings">Update Right Now post settings</a> <code>hidden: false</code>. It lowers <code>count</code> in <a href="/grindr-api/browse/entitlements#get-right-now-post-entitlements">Get Right Now post entitlements</a> by one.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/rightnow/posts</span></span></code></pre></div><p>Body:</p><ul><li><code>text</code> — string, optional</li><li><code>shareLocation</code> — <a href="/grindr-api/right-now#rightnowsharelocation">RightNowShareLocation</a></li><li><code>lat</code> — number, optional</li><li><code>lon</code> — number, optional</li><li><code>locationRadius</code> — integer, location precision from 0 to 100, not a distance in meters, optional</li><li><code>media</code> — array of objects <ul><li><code>type</code> — string, <code>&quot;image_v1&quot;</code></li><li><code>data</code> — object <ul><li><code>id</code> — long integer, the <code>mediaId</code> returned by <a href="/grindr-api/right-now#upload-right-now-media">Upload Right Now media</a> or <a href="/grindr-api/right-now#upload-right-now-media-v2">Upload Right Now media (v2)</a>; one <code>mediaId</code> can be attached to more than one post</li></ul></li></ul></li><li><code>hosting</code> — boolean</li></ul><p>Response:</p><ul><li><code>post</code> — <a href="/grindr-api/right-now#rightnowpostdetails">RightNowPostDetails</a></li></ul><h2 id="create-right-now-post" tabindex="-1">Create Right Now post <a class="header-anchor" href="#create-right-now-post" aria-label="Permalink to “Create Right Now post”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Start a Right Now post. It is <code>ACTIVE</code> at once and expires 60 minutes after <code>posted</code>. Without <code>lat</code> and <code>lon</code> it takes the location set by <a href="/grindr-api/browse/location#update-location">Update location</a>. The text waits in <code>moderatedText</code> with <code>textStatus</code> <code>AWAITING_MODERATION</code> and moves to <code>activeText</code> once approved. Each post lowers <code>count</code> in <a href="/grindr-api/browse/entitlements#get-right-now-post-entitlements">Get Right Now post entitlements</a> by one. With <code>count</code> at 0 the request still succeeds, but the post has <code>postStatus</code> <code>AWAITING_PAYMENT</code> with <code>posted</code> and <code>expiration</code> <code>null</code>; <a href="/grindr-api/right-now#get-own-right-now-post">Get own Right Now post</a> then returns <code>{&quot;post&quot;:null}</code>, the post is absent from the feed, and <a href="/grindr-api/right-now#get-right-now-post-by-profile">Get Right Now post by profile</a> returns <code>{&quot;post&quot;:null}</code> for it.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v3/rightnow/posts</span></span></code></pre></div><p>Body:</p><ul><li><code>text</code> — string, optional</li><li><code>shareLocation</code> — <a href="/grindr-api/right-now#rightnowsharelocation">RightNowShareLocation</a></li><li><code>lat</code> — number, optional</li><li><code>lon</code> — number, optional</li><li><code>locationRadius</code> — integer, location precision from 0 to 100, not a distance in meters, optional</li><li><code>media</code> — array of objects <ul><li><code>type</code> — string, <code>&quot;image_v1&quot;</code></li><li><code>data</code> — object <ul><li><code>id</code> — long integer, the <code>mediaId</code> returned by <a href="/grindr-api/right-now#upload-right-now-media">Upload Right Now media</a> or <a href="/grindr-api/right-now#upload-right-now-media-v2">Upload Right Now media (v2)</a>; one <code>mediaId</code> can be attached to more than one post</li></ul></li></ul></li><li><code>hosting</code> — boolean</li></ul><p>Response:</p><ul><li><code>post</code> — <a href="/grindr-api/right-now#rightnowpostdetails">RightNowPostDetails</a></li></ul><p>Errors:</p><ul><li><code>400</code> — <code>urn:gr:err:client_action</code> while the account has an active or hidden post.</li></ul><h2 id="update-right-now-post-settings" tabindex="-1">Update Right Now post settings <a class="header-anchor" href="#update-right-now-post-settings" aria-label="Permalink to “Update Right Now post settings”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Update hosting, location sharing, or visibility. Send hidden: true to deactivate the post and hidden: false to reactivate it before expiration; this preserves its identity and expiration. A hidden post has <code>postStatus</code> <code>HIDDEN</code>, leaves the feed, and <a href="/grindr-api/right-now#get-right-now-post-by-profile">Get Right Now post by profile</a> returns <code>{&quot;post&quot;:null}</code> for it. Hiding and unhiding do not change <code>count</code> in <a href="/grindr-api/browse/entitlements#get-right-now-post-entitlements">Get Right Now post entitlements</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATCH /v1/rightnow/posts/{postId}/settings</span></span></code></pre></div><p>Body:</p><ul><li><code>shareLocation</code> — <a href="/grindr-api/right-now#rightnowsharelocation">RightNowShareLocation</a>, optional</li><li><code>hosting</code> — boolean, optional</li><li><code>hidden</code> — boolean, <code>true</code> hides the post and <code>false</code> makes it active again, optional</li></ul><p>Errors:</p><ul><li><code>400</code> — <code>urn:gr:err:client_action</code> when the body has no recognized settings key (<code>hosting</code>, <code>shareLocation</code> or <code>hidden</code>), checked before the post ID. <code>urn:gr:err:internal_error</code> for an unknown <code>shareLocation</code> value. <code>urn:gr:err:resource_not_found</code> when no post has this ID. <code>urn:gr:err:client_action</code> for <code>hidden: false</code> on an expired post.</li></ul><h2 id="get-right-now-feed-v5" tabindex="-1">Get Right Now feed (v5) <a class="header-anchor" href="#get-right-now-feed-v5" aria-label="Permalink to “Get Right Now feed (v5)”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Get the Right Now feed (v5), with the same items, response shape and query parameters as v4. DISTANCE orders posts by ascending distance; NEWEST, the default, orders posts by descending posted time. Multiple sexualPositions select their union; position and hosting filters combine as an intersection. An active own post can remain included despite age and position filters. Card representation may change with filters, so filtered standard-post sets need not be subsets of unfiltered standard-post sets.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v5/rightnow/feed</span></span></code></pre></div><p>Query (optional):</p><ul><li><code>sort</code> — string, sort order, optional</li><li><code>hosting</code> — boolean, true selects hosting posts; false selects non-hosting posts. Omit to include both., optional</li><li><code>sexualPositions</code> — array of integers concatenated with a <code>,</code>, <code>-1</code> means &quot;Not Specified&quot;, see <a href="/grindr-api/users/profiles#sexual-position-id">Sexual position</a>, optional</li><li><code>ageMin</code> — integer, optional</li><li><code>ageMax</code> — integer, optional</li></ul><p>Response:</p><ul><li><code>items</code> — array of <a href="/grindr-api/right-now#rightnowfeedresponseitem">RightNowFeedResponseItem</a></li><li><code>viewerCount</code> — number of profiles currently viewing the feed area</li></ul><p>Errors:</p><ul><li><code>500</code> — <code>urn:gr:err:internal_error</code> for a <code>sexualPositions</code> value that is not a list of integers, such as <code>abc</code>.</li></ul><h2 id="upload-right-now-media" tabindex="-1">Upload Right Now media <a class="header-anchor" href="#upload-right-now-media" aria-label="Permalink to “Upload Right Now media”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Upload raw image bytes as image/jpeg or application/octet-stream. Attach the returned mediaId as image_v1 data.id when creating or editing a post.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/media/upload</span></span></code></pre></div><p>Query (optional):</p><ul><li><code>img_1_bottom</code> — integer, optional</li><li><code>img_1_left</code> — integer, optional</li><li><code>img_1_right</code> — integer, optional</li><li><code>img_1_top</code> — integer, optional</li></ul><p>Body:</p><p>Binary file.</p><p>Response:</p><ul><li><code>mediaId</code> — long integer</li><li><code>url</code> — URL</li><li><code>thumbnailUrl</code> — URL</li></ul><h2 id="get-right-now-google-play-skus" tabindex="-1">Get Right Now Google Play SKUs <a class="header-anchor" href="#get-right-now-google-play-skus" aria-label="Permalink to “Get Right Now Google Play SKUs”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/rightnow/googleplay/sku</span></span></code></pre></div><p>Response:</p><ul><li><code>rightNowSku</code> — string</li><li><code>rightNowBoostedSku</code> — string</li><li><code>boostUpsellSku</code> — string</li></ul><h2 id="send-right-now-request" tabindex="-1">Send Right Now request <a class="header-anchor" href="#send-right-now-request" aria-label="Permalink to “Send Right Now request”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Ask the author of a Right Now post to chat, discreet posts included, whose feed items carry no <code>profileId</code>. The author sees the request in <a href="/grindr-api/right-now#get-received-right-now-requests">Get received Right Now requests</a> while the post is active and answers it with <a href="/grindr-api/right-now#update-right-now-request">Update Right Now request</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/rightnow/requests</span></span></code></pre></div><p>Body:</p><ul><li><code>postId</code> — long integer</li></ul><p>Errors:</p><ul><li><code>409</code> — <code>urn:gr:err:internal_error</code> when the caller already sent a request for this post.</li></ul><h2 id="upload-right-now-media-v2" tabindex="-1">Upload Right Now media (v2) <a class="header-anchor" href="#upload-right-now-media-v2" aria-label="Permalink to “Upload Right Now media (v2)”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Upload raw, uncropped image bytes as image/jpeg or application/octet-stream with a separate crop rectangle (<code>crop_*</code>), a thumbnail crop (<code>img_1_*</code>), plus <code>rotate</code> and <code>flip_vertical</code>. Attach the returned mediaId as image_v1 data.id when creating or editing a post.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v2/media/upload</span></span></code></pre></div><p>Query:</p><ul><li><code>crop_top</code> — integer</li><li><code>crop_bottom</code> — integer</li><li><code>crop_left</code> — integer</li><li><code>crop_right</code> — integer</li><li><code>img_1_top</code> — integer</li><li><code>img_1_bottom</code> — integer</li><li><code>img_1_left</code> — integer</li><li><code>img_1_right</code> — integer</li><li><code>rotate</code> — integer, 0, 90, 180 or 270</li><li><code>flip_vertical</code> — boolean</li></ul><p>Body:</p><p>Binary file.</p><p>Response:</p><ul><li><code>mediaId</code> — long integer</li><li><code>url</code> — URL</li><li><code>thumbnailUrl</code> — URL</li></ul><p>Errors:</p><ul><li><code>400</code> — <code>urn:gr:err:bad_request</code> (<code>Invalid request</code>, detail <code>Bytes too few</code>) for a very small file, such as a 5 KB JPEG.</li></ul><h2 id="get-received-right-now-requests" tabindex="-1">Get received Right Now requests <a class="header-anchor" href="#get-received-right-now-requests" aria-label="Permalink to “Get received Right Now requests”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Requests for the caller&#39;s post. A hidden post&#39;s requests are left out until it is shown again, and an expired post&#39;s requests are gone.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/rightnow/requests/inbox</span></span></code></pre></div><p>Response:</p><ul><li><code>requests</code> — array of objects <ul><li><code>id</code> — long integer, the <code>requestId</code> for <a href="/grindr-api/right-now#update-right-now-request">Update Right Now request</a></li><li><code>profileId</code> — long integer, profile ID of the sender</li><li><code>displayName</code> — string or <code>null</code></li><li><code>primaryMediaHash</code> — string, See <a href="/grindr-api/media/public-cdn-files#profile-images">Media -&gt; Public CDN files -&gt; Profile Images</a> or <code>null</code></li><li><code>distance</code> — integer or <code>null</code>, distance in meters</li><li><code>status</code> — string, <code>&quot;PENDING&quot;</code>, <code>&quot;ACCEPTED&quot;</code> or <code>&quot;REJECTED&quot;</code></li><li><code>postId</code> — long integer</li><li><code>createdAt</code> — unix timestamp in milliseconds</li><li><code>updatedAt</code> — unix timestamp in milliseconds</li><li><code>onlineUntil</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>favorite</code> — boolean</li></ul></li></ul><h2 id="get-sent-right-now-requests" tabindex="-1">Get sent Right Now requests <a class="header-anchor" href="#get-sent-right-now-requests" aria-label="Permalink to “Get sent Right Now requests”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Requests the caller sent, including accepted ones for expired posts.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/rightnow/requests/outbox</span></span></code></pre></div><p>Response:</p><ul><li><code>requests</code> — array of objects <ul><li><code>recipientProfileId</code> — long integer or <code>null</code>, the post author&#39;s profile ID once the request is <code>&quot;ACCEPTED&quot;</code>, otherwise <code>null</code></li><li><code>status</code> — string, <code>&quot;PENDING&quot;</code>, <code>&quot;ACCEPTED&quot;</code> or <code>&quot;REJECTED&quot;</code></li><li><code>postId</code> — long integer</li><li><code>createdAt</code> — unix timestamp in milliseconds</li><li><code>updatedAt</code> — unix timestamp in milliseconds</li></ul></li></ul><h2 id="update-right-now-request" tabindex="-1">Update Right Now request <a class="header-anchor" href="#update-right-now-request" aria-label="Permalink to “Update Right Now request”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p><code>requestId</code> is the <code>id</code> of a request from <a href="/grindr-api/right-now#get-received-right-now-requests">Get received Right Now requests</a>. Accepting adds a <code>RightNowRequest</code> message from the post author to the conversation with the sender and reveals the author in the sender&#39;s <a href="/grindr-api/right-now#get-sent-right-now-requests">Get sent Right Now requests</a>. A rejected request can still be accepted later.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PUT /v1/rightnow/requests/{requestId}</span></span></code></pre></div><p>Body:</p><ul><li><code>status</code> — string, <code>&quot;ACCEPTED&quot;</code> or <code>&quot;REJECTED&quot;</code></li></ul><h2 id="get-right-now-feed" tabindex="-1">Get Right Now feed <a class="header-anchor" href="#get-right-now-feed" aria-label="Permalink to “Get Right Now feed”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Get the Right Now feed. DISTANCE orders posts by ascending distance; NEWEST, the default, orders posts by descending posted time. Multiple sexualPositions select their union; position and hosting filters combine as an intersection. An active own post can remain included despite age and position filters. Card representation may change with filters, so filtered standard-post sets need not be subsets of unfiltered standard-post sets. A post stays listed near where it was posted after its author moves, while <code>distance</code>, <code>lat</code> and <code>lon</code> follow the author&#39;s current location. Reading the feed refreshes the caller&#39;s <code>onlineUntil</code>. v4, v5 and v6 return the same items, discreet posts included.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v4/rightnow/feed</span></span></code></pre></div><p>Query (optional):</p><ul><li><code>sort</code> — string, sort order, optional</li><li><code>hosting</code> — boolean, true selects hosting posts; false selects non-hosting posts. Omit to include both., optional</li><li><code>sexualPositions</code> — array of integers concatenated with a <code>,</code>, <code>-1</code> means &quot;Not Specified&quot;, see <a href="/grindr-api/users/profiles#sexual-position-id">Sexual position</a>, optional</li><li><code>ageMin</code> — integer, optional</li><li><code>ageMax</code> — integer, optional</li></ul><p>Response:</p><ul><li><code>items</code> — array of <a href="/grindr-api/right-now#rightnowfeedresponseitem">RightNowFeedResponseItem</a></li><li><code>viewerCount</code> — number of profiles currently viewing the feed area</li></ul><p>Errors:</p><ul><li><code>400</code> — <code>urn:gr:err:client_action</code> (<code>Action not allowed at this time</code>) until the caller sets a location with <a href="/grindr-api/browse/location#update-location">Update location</a>.</li><li><code>500</code> — <code>urn:gr:err:internal_error</code> for a <code>sexualPositions</code> value that is not a list of integers, such as <code>abc</code>.</li></ul><h2 id="get-right-now-feed-v6" tabindex="-1">Get Right Now feed (v6) <a class="header-anchor" href="#get-right-now-feed-v6" aria-label="Permalink to “Get Right Now feed (v6)”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Get the Right Now feed (v6), with the same items, response shape and query parameters as v4. DISTANCE orders posts by ascending distance; NEWEST, the default, orders posts by descending posted time. Multiple sexualPositions select their union; position and hosting filters combine as an intersection. An active own post can remain included despite age and position filters. Card representation may change with filters, so filtered standard-post sets need not be subsets of unfiltered standard-post sets.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v6/rightnow/feed</span></span></code></pre></div><p>Query (optional):</p><ul><li><code>sort</code> — string, sort order, optional</li><li><code>hosting</code> — boolean, true selects hosting posts; false selects non-hosting posts. Omit to include both., optional</li><li><code>sexualPositions</code> — array of integers concatenated with a <code>,</code>, <code>-1</code> means &quot;Not Specified&quot;, see <a href="/grindr-api/users/profiles#sexual-position-id">Sexual position</a>, optional</li><li><code>ageMin</code> — integer, optional</li><li><code>ageMax</code> — integer, optional</li></ul><p>Response:</p><ul><li><code>items</code> — array of <a href="/grindr-api/right-now#rightnowfeedresponseitem">RightNowFeedResponseItem</a></li><li><code>viewerCount</code> — number of profiles currently viewing the feed area</li></ul><p>Errors:</p><ul><li><code>500</code> — <code>urn:gr:err:internal_error</code> for a <code>sexualPositions</code> value that is not a list of integers, such as <code>abc</code>.</li></ul><h2 id="get-hookup-intent-post" tabindex="-1">Get hookup intent post <a class="header-anchor" href="#get-hookup-intent-post" aria-label="Permalink to “Get hookup intent post”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Returns your hookup intent post. Answers <code>204</code> with an empty body when you have none.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/hookup-intent/post</span></span></code></pre></div><p>Response:</p><ul><li><code>post</code> — <a href="/grindr-api/right-now#hookupintentpost">HookupIntentPost</a> or <code>null</code></li><li><code>status</code> — string, <code>&quot;ACTIVE&quot;</code>, <code>&quot;INACTIVE&quot;</code> (see <a href="/grindr-api/right-now#renew-hookup-intent-post">Renew hookup intent post</a>) or <code>null</code></li><li><code>renewsIn</code> — long integer, appears to be the number of seconds until the post has to be <a href="/grindr-api/right-now#renew-hookup-intent-post">renewed</a>, or <code>null</code></li></ul><h2 id="create-hookup-intent-post" tabindex="-1">Create hookup intent post <a class="header-anchor" href="#create-hookup-intent-post" aria-label="Permalink to “Create hookup intent post”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Turns hookup intent on by creating your post.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/hookup-intent/post</span></span></code></pre></div><p>Body:</p><ul><li><code>text</code> — string, optional</li><li><code>shareLocation</code> — <a href="/grindr-api/right-now#rightnowsharelocation">RightNowShareLocation</a></li><li><code>locationRadius</code> — integer, optional</li><li><code>media</code> — array of objects, may be empty <ul><li><code>type</code> — string, <code>&quot;image_v1&quot;</code> or <code>&quot;album_v1&quot;</code></li><li><code>data</code> — object <ul><li><code>id</code> — long integer, media ID; for <code>&quot;image_v1&quot;</code> the <code>mediaId</code> returned by a Right Now media upload, see <a href="/grindr-api/right-now#upload-right-now-media">Upload right now media</a> and <a href="/grindr-api/right-now#upload-right-now-media-v2">Upload Right Now media (v2)</a></li></ul></li></ul></li><li><code>hosting</code> — boolean</li></ul><p>Response:</p><ul><li><code>post</code> — <a href="/grindr-api/right-now#hookupintentpost">HookupIntentPost</a></li><li><code>status</code> — string, <code>&quot;ACTIVE&quot;</code>, <code>&quot;INACTIVE&quot;</code> (see <a href="/grindr-api/right-now#renew-hookup-intent-post">Renew hookup intent post</a>) or <code>null</code></li><li><code>renewsIn</code> — long integer, appears to be the number of seconds until the post has to be <a href="/grindr-api/right-now#renew-hookup-intent-post">renewed</a>, or <code>null</code></li></ul><p>Errors:</p><ul><li><code>409</code> — Conflicts with the current post state.</li></ul><h2 id="update-hookup-intent-post" tabindex="-1">Update hookup intent post <a class="header-anchor" href="#update-hookup-intent-post" aria-label="Permalink to “Update hookup intent post”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Only the fields present in the request body are updated.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PUT /v1/hookup-intent/post/{postId}</span></span></code></pre></div><p>Body:</p><ul><li><code>text</code> — string</li><li><code>hosting</code> — boolean</li><li><code>media</code> — array of objects, optional; an empty array appears to remove the photo <ul><li><code>type</code> — string, <code>&quot;image_v1&quot;</code> or <code>&quot;album_v1&quot;</code></li><li><code>data</code> — object <ul><li><code>id</code> — long integer, media ID; for <code>&quot;image_v1&quot;</code> the <code>mediaId</code> returned by a Right Now media upload, see <a href="/grindr-api/right-now#upload-right-now-media">Upload right now media</a> and <a href="/grindr-api/right-now#upload-right-now-media-v2">Upload Right Now media (v2)</a></li></ul></li></ul></li><li><code>shareLocation</code> — <a href="/grindr-api/right-now#rightnowsharelocation">RightNowShareLocation</a></li><li><code>locationRadius</code> — integer</li></ul><p>Response:</p><ul><li><code>post</code> — <a href="/grindr-api/right-now#hookupintentpost">HookupIntentPost</a></li><li><code>status</code> — string, <code>&quot;ACTIVE&quot;</code>, <code>&quot;INACTIVE&quot;</code> (see <a href="/grindr-api/right-now#renew-hookup-intent-post">Renew hookup intent post</a>) or <code>null</code></li><li><code>renewsIn</code> — long integer, appears to be the number of seconds until the post has to be <a href="/grindr-api/right-now#renew-hookup-intent-post">renewed</a>, or <code>null</code></li></ul><h2 id="delete-hookup-intent-post" tabindex="-1">Delete hookup intent post <a class="header-anchor" href="#delete-hookup-intent-post" aria-label="Permalink to “Delete hookup intent post”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Turns hookup intent off.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DELETE /v1/hookup-intent/post/{postId}</span></span></code></pre></div><h2 id="renew-hookup-intent-post" tabindex="-1">Renew hookup intent post <a class="header-anchor" href="#renew-hookup-intent-post" aria-label="Permalink to “Renew hookup intent post”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Renews your hookup intent post, see <code>status</code> and <code>renewsIn</code> in <a href="/grindr-api/right-now#get-hookup-intent-post">Get hookup intent post</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/hookup-intent/post/{postId}/renew</span></span></code></pre></div><p>Response:</p><ul><li><code>post</code> — <a href="/grindr-api/right-now#hookupintentpost">HookupIntentPost</a></li><li><code>status</code> — string, <code>&quot;ACTIVE&quot;</code>, <code>&quot;INACTIVE&quot;</code> (see <a href="/grindr-api/right-now#renew-hookup-intent-post">Renew hookup intent post</a>) or <code>null</code></li><li><code>renewsIn</code> — long integer, appears to be the number of seconds until the post has to be <a href="/grindr-api/right-now#renew-hookup-intent-post">renewed</a>, or <code>null</code></li></ul><p>Errors:</p><ul><li><code>404</code> — No such post.</li><li><code>409</code> — Conflicts with the current post state.</li></ul><h2 id="hookupintentpost" tabindex="-1">HookupIntentPost <a class="header-anchor" href="#hookupintentpost" aria-label="Permalink to “HookupIntentPost”">​</a></h2><p>Your hookup intent post.</p><ul><li><code>id</code> — long integer</li><li><code>profileId</code> — long integer</li><li><code>posted</code> — unix timestamp in milliseconds or <code>null</code>, optional</li><li><code>expiration</code> — unix timestamp in milliseconds or <code>null</code>, optional</li><li><code>hosting</code> — boolean, optional</li><li><code>activeText</code> — string or <code>null</code>, the post&#39;s live text; <code>moderatedText</code> holds the latest submitted text, optional</li><li><code>moderatedText</code> — object, the latest submitted text and its moderation state, or <code>null</code>, optional <ul><li><code>id</code> — long integer</li><li><code>postId</code> — long integer</li><li><code>text</code> — string</li><li><code>textStatus</code> — string or <code>null</code>, known values: <code>&quot;AWAITING_MODERATION&quot;</code>, <code>&quot;MODERATION_FAILED&quot;</code>, <code>&quot;ERROR&quot;</code></li><li><code>rejectReasons</code> — array of strings or <code>null</code></li><li><code>createdAt</code> — long integer</li><li><code>updatedAt</code> — long integer</li></ul></li><li><code>media</code> — array of objects or <code>null</code>, optional <ul><li><code>mediaId</code> — long integer</li><li><code>thumbnailUrl</code> — URL</li><li><code>fullImageUrl</code> — URL</li><li><code>contentType</code> — string, e.g. <code>image/jpeg</code></li><li><code>state</code> — string, <code>&quot;PENDING&quot;</code>, <code>&quot;APPROVED&quot;</code>, <code>&quot;REJECTED&quot;</code>, <code>&quot;DELETED&quot;</code> or <code>null</code></li><li><code>reason</code> — string or <code>null</code></li><li><code>isRejectAutomated</code> — boolean or <code>null</code></li><li><code>shouldBlur</code> — boolean, may be absent</li><li><code>isNsfw</code> — boolean, may be absent</li></ul></li><li><code>lat</code> — number or <code>null</code>, optional</li><li><code>lon</code> — number or <code>null</code>, optional</li><li><code>postStatus</code> — string, <code>&quot;ACTIVE&quot;</code>, <code>&quot;INACTIVE&quot;</code> or <code>null</code>, optional</li><li><code>shareLocation</code> — <a href="/grindr-api/right-now#rightnowsharelocation">RightNowShareLocation</a> or <code>null</code>, optional</li><li><code>locationRadius</code> — integer or <code>null</code>, optional</li><li><code>isDiscreet</code> — string, <code>&quot;TRUE&quot;</code>, <code>&quot;FALSE&quot;</code> or <code>null</code>, optional</li><li><code>sharedFields</code> — array of strings or <code>null</code>, optional</li></ul><h2 id="rightnowstatus" tabindex="-1">RightNowStatus <a class="header-anchor" href="#rightnowstatus" aria-label="Permalink to “RightNowStatus”">​</a></h2><ul><li><code>&quot;NOT_ACTIVE&quot;</code></li><li><code>&quot;HOSTING&quot;</code></li><li><code>&quot;NOT_HOSTING&quot;</code></li></ul><h2 id="rightnowattributionstatus" tabindex="-1">RightNowAttributionStatus <a class="header-anchor" href="#rightnowattributionstatus" aria-label="Permalink to “RightNowAttributionStatus”">​</a></h2><p>Right Now attribution status. Sent as a plain string under key <code>rightNowStatus</code>.</p><ul><li><code>&quot;ACTIVE&quot;</code></li><li><code>&quot;HIDDEN&quot;</code></li><li><code>&quot;ACTIVE_WITH_BOOST&quot;</code></li><li><code>&quot;NONE&quot;</code></li></ul><h2 id="rightnowsharelocation" tabindex="-1">RightNowShareLocation <a class="header-anchor" href="#rightnowsharelocation" aria-label="Permalink to “RightNowShareLocation”">​</a></h2><ul><li><code>&quot;DISTANCE_AND_MAP&quot;</code></li><li><code>&quot;DISTANCE_ONLY&quot;</code></li><li><code>&quot;NONE&quot;</code></li></ul><h2 id="rightnowfeedresponse" tabindex="-1">RightNowFeedResponse <a class="header-anchor" href="#rightnowfeedresponse" aria-label="Permalink to “RightNowFeedResponse”">​</a></h2><ul><li><code>items</code> — array of <a href="/grindr-api/right-now#rightnowfeedresponseitem">RightNowFeedResponseItem</a></li><li><code>viewerCount</code> — number of profiles currently viewing the feed area</li></ul><h2 id="rightnowfeedresponseitem" tabindex="-1">RightNowFeedResponseItem <a class="header-anchor" href="#rightnowfeedresponseitem" aria-label="Permalink to “RightNowFeedResponseItem”">​</a></h2><p>A feed item, discriminated by <code>type</code>.</p><ul><li><code>type</code> — string, <code>&quot;right_now_post_v3&quot;</code> (<a href="/grindr-api/right-now#rightnowpost">RightNowPost</a>), <code>&quot;locked_post_v1&quot;</code> (<a href="/grindr-api/right-now#lockedpost">LockedPost</a>), <code>&quot;curated_post_v1&quot;</code> (<a href="/grindr-api/right-now#curatedpost">CuratedPost</a>), <code>&quot;discreet_right_now_post_v1&quot;</code> (<a href="/grindr-api/right-now#discreetpost">DiscreetPost</a>), <code>&quot;discreet_locked_post_v1&quot;</code> (<a href="/grindr-api/right-now#discreetlockedpost">DiscreetLockedPost</a>) or <code>&quot;upsell_insert_v1&quot;</code> (<a href="/grindr-api/right-now#upsellinsert">UpsellInsert</a>)</li><li><code>data</code> — object, optional</li></ul><h2 id="curatedpost" tabindex="-1">CuratedPost <a class="header-anchor" href="#curatedpost" aria-label="Permalink to “CuratedPost”">​</a></h2><ul><li><code>type</code> — string, <code>&quot;curated_post_v1&quot;</code></li><li><code>data</code> — <a href="/grindr-api/right-now#curatedpostdata">CuratedPostData</a>, optional</li></ul><h2 id="rightnowpost" tabindex="-1">RightNowPost <a class="header-anchor" href="#rightnowpost" aria-label="Permalink to “RightNowPost”">​</a></h2><ul><li><code>type</code> — string, <code>&quot;right_now_post_v3&quot;</code></li><li><code>data</code> — <a href="/grindr-api/right-now#postdata">PostData</a>, optional</li></ul><h2 id="lockedpost" tabindex="-1">LockedPost <a class="header-anchor" href="#lockedpost" aria-label="Permalink to “LockedPost”">​</a></h2><ul><li><code>type</code> — string, <code>&quot;locked_post_v1&quot;</code></li><li><code>data</code> — <a href="/grindr-api/right-now#postdata">PostData</a>, optional</li></ul><h2 id="postdata" tabindex="-1">PostData <a class="header-anchor" href="#postdata" aria-label="Permalink to “PostData”">​</a></h2><ul><li><code>@type</code> — string, server post-data label, e.g. <code>RightNowFeedItemData$RightNowPostV3</code> or <code>$LockedPostV1</code></li><li><code>id</code> — long integer</li><li><code>profileId</code> — long integer</li><li><code>mediaHash</code> — string, optional</li><li><code>displayName</code> — string, optional</li><li><code>media</code> — array of <a href="/grindr-api/right-now#rightnowpostmediaitem">RightNowPostMediaItem</a></li><li><code>onlineUntil</code> — unix timestamp in milliseconds; present on <code>right_now_post_v3</code>, absent on <code>locked_post_v1</code>; may be absent, optional</li><li><code>text</code> — string, optional</li><li><code>distance</code> — integer, distance in meters; may be absent, optional</li><li><code>mpuScore</code> — float, optional</li><li><code>type</code> — string, <code>&quot;xtra_post_v1&quot;</code> or <code>&quot;unlimited_post_v1&quot;</code>, locked-post kind; present only on <code>locked_post_v1</code>; may be absent, optional</li><li><code>hosting</code> — boolean</li><li><code>posted</code> — unix timestamp in milliseconds</li><li><code>expiration</code> — unix timestamp in milliseconds</li><li><code>recentlyChatted</code> — boolean</li><li><code>favorite</code> — boolean</li><li><code>lat</code> — number, latitude; may be absent, optional</li><li><code>lon</code> — number, longitude; may be absent, optional</li><li><code>isOnPrep</code> — boolean, whether the profile is on PrEP; absent on <code>locked_post_v1</code>, optional</li></ul><h2 id="rightnowpostmediaitem" tabindex="-1">RightNowPostMediaItem <a class="header-anchor" href="#rightnowpostmediaitem" aria-label="Permalink to “RightNowPostMediaItem”">​</a></h2><ul><li><code>type</code> — string, <code>&quot;image_v1&quot;</code> or <code>&quot;album_v1&quot;</code>, optional</li><li><code>data</code> — object, optional <ul><li><code>mediaId</code> — long integer</li><li><code>thumbnailUrl</code> — URL</li><li><code>fullImageUrl</code> — URL</li><li><code>contentType</code> — string, e.g. <code>image/jpeg</code></li><li><code>state</code> — string, moderation state, known values: <code>&quot;PENDING&quot;</code>, <code>&quot;APPROVED&quot;</code>, <code>&quot;REJECTED&quot;</code>, <code>&quot;DELETED&quot;</code></li><li><code>reason</code> — string, moderation reason or <code>null</code></li><li><code>isRejectAutomated</code> — boolean or <code>null</code></li><li><code>shouldBlur</code> — boolean</li><li><code>isNsfw</code> — boolean</li><li><code>source</code> — string, e.g. <code>RIGHT_NOW</code></li></ul></li></ul><h2 id="curatedpostdata" tabindex="-1">CuratedPostData <a class="header-anchor" href="#curatedpostdata" aria-label="Permalink to “CuratedPostData”">​</a></h2><ul><li><code>@type</code> — string, e.g. <code>RightNowFeedItemData$CuratedPostV1</code>, optional</li><li><code>type</code> — string, <code>&quot;tutorial_australia_v1&quot;</code>, <code>&quot;tutorial_hosting_v1&quot;</code> or <code>&quot;tutorial_dense_market_v1&quot;</code>, optional</li></ul><h2 id="upsellinsertdata" tabindex="-1">UpsellInsertData <a class="header-anchor" href="#upsellinsertdata" aria-label="Permalink to “UpsellInsertData”">​</a></h2><ul><li><code>@type</code> — string, e.g. <code>RightNowFeedItemData$UpsellInsertV1</code>, optional</li><li><code>type</code> — string, <code>&quot;xtra_upsell_v1&quot;</code> or <code>&quot;unlimited_upsell_v1&quot;</code>, optional</li></ul><h2 id="discreetpostdata" tabindex="-1">DiscreetPostData <a class="header-anchor" href="#discreetpostdata" aria-label="Permalink to “DiscreetPostData”">​</a></h2><p>Has no <code>profileId</code>; reach the author with <a href="/grindr-api/right-now#send-right-now-request">Send Right Now request</a>.</p><ul><li><code>@type</code> — string, server post-data label, e.g. <code>RightNowFeedItemData$DiscreetRightNowPostV1</code>, optional</li><li><code>id</code> — long integer</li><li><code>media</code> — array of <a href="/grindr-api/right-now#rightnowpostmediaitem">RightNowPostMediaItem</a>, optional</li><li><code>onlineUntil</code> — unix timestamp in milliseconds; may be absent, optional</li><li><code>text</code> — string, optional</li><li><code>distance</code> — integer, distance in meters; may be absent, optional</li><li><code>lat</code> — number, latitude; may be absent, optional</li><li><code>lon</code> — number, longitude; may be absent, optional</li><li><code>type</code> — string, <code>&quot;xtra_post_v1&quot;</code> or <code>&quot;unlimited_post_v1&quot;</code>, locked-post kind; may be absent, optional</li><li><code>hosting</code> — boolean</li><li><code>posted</code> — unix timestamp in milliseconds</li><li><code>expiration</code> — unix timestamp in milliseconds</li><li><code>profileFields</code> — object, the author&#39;s profile values <ul><li><code>age</code> — integer or <code>null</code></li><li><code>height</code> — number or <code>null</code></li><li><code>weight</code> — number or <code>null</code></li><li><code>position</code> — integer or <code>null</code></li></ul></li></ul><h2 id="discreetpost" tabindex="-1">DiscreetPost <a class="header-anchor" href="#discreetpost" aria-label="Permalink to “DiscreetPost”">​</a></h2><ul><li><code>type</code> — string, <code>&quot;discreet_right_now_post_v1&quot;</code></li><li><code>data</code> — <a href="/grindr-api/right-now#discreetpostdata">DiscreetPostData</a>, optional</li></ul><h2 id="discreetlockedpost" tabindex="-1">DiscreetLockedPost <a class="header-anchor" href="#discreetlockedpost" aria-label="Permalink to “DiscreetLockedPost”">​</a></h2><ul><li><code>type</code> — string, <code>&quot;discreet_locked_post_v1&quot;</code></li><li><code>data</code> — <a href="/grindr-api/right-now#discreetpostdata">DiscreetPostData</a>, optional</li></ul><h2 id="upsellinsert" tabindex="-1">UpsellInsert <a class="header-anchor" href="#upsellinsert" aria-label="Permalink to “UpsellInsert”">​</a></h2><ul><li><code>type</code> — string, <code>&quot;upsell_insert_v1&quot;</code></li><li><code>data</code> — <a href="/grindr-api/right-now#upsellinsertdata">UpsellInsertData</a>, optional</li></ul><h2 id="rightnowmediauploadresponse" tabindex="-1">RightNowMediaUploadResponse <a class="header-anchor" href="#rightnowmediauploadresponse" aria-label="Permalink to “RightNowMediaUploadResponse”">​</a></h2><p>Response from either Right Now media upload version. Attach mediaId as image_v1 data.id when creating or editing a post.</p><ul><li><code>mediaId</code> — long integer</li><li><code>url</code> — URL</li><li><code>thumbnailUrl</code> — URL</li></ul><h2 id="rightnowpostrequest" tabindex="-1">RightNowPostRequest <a class="header-anchor" href="#rightnowpostrequest" aria-label="Permalink to “RightNowPostRequest”">​</a></h2><ul><li><code>text</code> — string, optional</li><li><code>shareLocation</code> — <a href="/grindr-api/right-now#rightnowsharelocation">RightNowShareLocation</a></li><li><code>lat</code> — number, optional</li><li><code>lon</code> — number, optional</li><li><code>locationRadius</code> — integer, location precision from 0 to 100, not a distance in meters, optional</li><li><code>media</code> — array of objects <ul><li><code>type</code> — string, <code>&quot;image_v1&quot;</code></li><li><code>data</code> — object <ul><li><code>id</code> — long integer, the <code>mediaId</code> returned by <a href="/grindr-api/right-now#upload-right-now-media">Upload Right Now media</a> or <a href="/grindr-api/right-now#upload-right-now-media-v2">Upload Right Now media (v2)</a>; one <code>mediaId</code> can be attached to more than one post</li></ul></li></ul></li><li><code>hosting</code> — boolean</li></ul><h2 id="rightnowpostdetails" tabindex="-1">RightNowPostDetails <a class="header-anchor" href="#rightnowpostdetails" aria-label="Permalink to “RightNowPostDetails”">​</a></h2><p>Right Now post returned by the own-post, profile-post and create endpoints. Text edits may leave activeText unchanged while moderatedText holds the submitted text and moderation state.</p><ul><li><code>id</code> — long integer</li><li><code>profileId</code> — long integer</li><li><code>posted</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>expiration</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>hosting</code> — boolean</li><li><code>activeText</code> — string or <code>null</code>, the post&#39;s live text; <code>moderatedText</code> holds the latest submitted text</li><li><code>moderatedText</code> — object, the latest submitted text and its moderation state, or <code>null</code><ul><li><code>id</code> — long integer</li><li><code>postId</code> — long integer</li><li><code>text</code> — string</li><li><code>textStatus</code> — string or <code>null</code>, known values: <code>&quot;AWAITING_MODERATION&quot;</code>, <code>&quot;MODERATION_FAILED&quot;</code>, <code>&quot;ERROR&quot;</code></li><li><code>rejectReasons</code> — array of strings or <code>null</code>, known values: <code>&quot;BULLYING&quot;</code>, <code>&quot;SELF_HARM&quot;</code>, <code>&quot;DRUG_PATTERNS&quot;</code>, <code>&quot;HATE_SPEECH&quot;</code>, <code>&quot;SOL_SEX&quot;</code>, <code>&quot;SPAM_DISRUPT&quot;</code>, <code>&quot;UNDERAGE&quot;</code>, <code>&quot;OTHER&quot;</code></li><li><code>createdAt</code> — long integer</li><li><code>updatedAt</code> — long integer</li><li><code>deleted</code> — boolean</li></ul></li><li><code>media</code> — array of objects or <code>null</code><ul><li><code>mediaId</code> — long integer</li><li><code>thumbnailUrl</code> — URL</li><li><code>fullImageUrl</code> — URL</li><li><code>contentType</code> — string, e.g. <code>image/jpeg</code></li><li><code>state</code> — string, moderation state, known values: <code>&quot;PENDING&quot;</code>, <code>&quot;APPROVED&quot;</code>, <code>&quot;REJECTED&quot;</code>, <code>&quot;DELETED&quot;</code></li><li><code>reason</code> — string, moderation reason or <code>null</code></li><li><code>isRejectAutomated</code> — boolean, Whether a rejection is automated; true alone does not indicate rejection. or <code>null</code></li><li><code>shouldBlur</code> — boolean</li><li><code>isNsfw</code> — boolean</li><li><code>source</code> — string, e.g. <code>RIGHT_NOW</code></li></ul></li><li><code>lat</code> — number or <code>null</code>, the author&#39;s current location set by <a href="/grindr-api/browse/location#update-location">Update location</a>; about 10 s after creation a fixed displacement (same distance and direction) is added, except in the create response and on an <code>AWAITING_PAYMENT</code> post. The post moves with the author, and a new <code>locationRadius</code> picks a new displacement</li><li><code>lon</code> — number or <code>null</code>, same as <code>lat</code></li><li><code>postStatus</code> — string, known values: <code>&quot;AWAITING_PAYMENT&quot;</code>, <code>&quot;AWAITING_MODERATION&quot;</code>, <code>&quot;ACTIVE&quot;</code>, <code>&quot;EXPIRED&quot;</code>, <code>&quot;HIDDEN&quot;</code>; a hidden post keeps its data</li><li><code>shareLocation</code> — <a href="/grindr-api/right-now#rightnowsharelocation">RightNowShareLocation</a> or <code>null</code></li><li><code>locationRadius</code> — integer, Location precision value from 0 to 100, or null. Not a distance in meters; null does not mean zero.</li><li><code>isDiscreet</code> — string or <code>null</code>: <code>&quot;NOT_SELECTED&quot;</code> on a new post, <code>&quot;FALSE&quot;</code> after a v4 edit of a <code>NOT_SELECTED</code> post, <code>&quot;TRUE&quot;</code> once the post is discreet</li><li><code>sharedFields</code> — array of strings or <code>null</code>, <code>&quot;AGE&quot;</code>, <code>&quot;HEIGHT&quot;</code>, <code>&quot;WEIGHT&quot;</code>, <code>&quot;POSITION&quot;</code></li><li><code>boostUpsellOfferAvailableUntil</code> — unix timestamp in milliseconds or <code>null</code></li></ul><h2 id="rightnowpostresponse" tabindex="-1">RightNowPostResponse <a class="header-anchor" href="#rightnowpostresponse" aria-label="Permalink to “RightNowPostResponse”">​</a></h2><ul><li><code>post</code> — <a href="/grindr-api/right-now#rightnowpostdetails">RightNowPostDetails</a> or <code>null</code></li></ul>',214)])])}const g=o(d,[["render",n]]);export{u as __pageData,g as default};
